import{_ as t,c as n,o as s,ag as e}from"./chunks/framework.CMajxlqO.js";const h=JSON.parse('{"title":"Kommunikation med frekvensomriktare","description":"","frontmatter":{},"headers":[],"relativePath":"06-kommunikation/frekvensomriktare-komm.md","filePath":"06-kommunikation/frekvensomriktare-komm.md","lastUpdated":1768470380000}'),r={name:"06-kommunikation/frekvensomriktare-komm.md"};function i(l,a,o,p,d,g){return s(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="kommunikation-med-frekvensomriktare" tabindex="-1">Kommunikation med frekvensomriktare <a class="header-anchor" href="#kommunikation-med-frekvensomriktare" aria-label="Permalink to &quot;Kommunikation med frekvensomriktare&quot;">​</a></h1><p>Frekvensomriktare (drives) är en central komponent i många automationssystem. I TIA Portal kommunicerar du med frekvensomriktare via <strong>Profinet</strong> eller <strong>Profibus</strong>, och styr hastighet, start/stopp och läser statusdata.</p><h2 id="vanliga-frekvensomriktare-fran-siemens" tabindex="-1">Vanliga frekvensomriktare från Siemens <a class="header-anchor" href="#vanliga-frekvensomriktare-fran-siemens" aria-label="Permalink to &quot;Vanliga frekvensomriktare från Siemens&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Serie</th><th>Effekt</th><th>Kommunikation</th><th>Användning</th></tr></thead><tbody><tr><td><strong>Sinamics G120</strong></td><td>0.37 - 250 kW</td><td>Profinet, Profibus</td><td>Standard industriapplikationer</td></tr><tr><td><strong>Sinamics G120C</strong></td><td>0.55 - 18.5 kW</td><td>Profinet, Profibus</td><td>Kompakt version</td></tr><tr><td><strong>Sinamics V20</strong></td><td>0.12 - 30 kW</td><td>USS, Modbus RTU</td><td>Enkel styrning utan Profinet</td></tr><tr><td><strong>Sinamics S120</strong></td><td>0.55 kW - MW</td><td>Profinet (hög prestanda)</td><td>Motion control, synkronisering</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Val av drive</p><p>För TIA Portal-integration, välj <strong>G120</strong> eller <strong>G120C</strong> med <strong>Profinet-modul</strong> (CU250S-2 PN). Detta ger full integration och enkel konfiguration.</p></div><h2 id="profinet-kommunikation-med-g120" tabindex="-1">Profinet-kommunikation med G120 <a class="header-anchor" href="#profinet-kommunikation-med-g120" aria-label="Permalink to &quot;Profinet-kommunikation med G120&quot;">​</a></h2><h3 id="forberedelser" tabindex="-1">Förberedelser <a class="header-anchor" href="#forberedelser" aria-label="Permalink to &quot;Förberedelser&quot;">​</a></h3><h4 id="_1-installera-gsdml-fil" tabindex="-1">1. Installera GSDML-fil <a class="header-anchor" href="#_1-installera-gsdml-fil" aria-label="Permalink to &quot;1. Installera GSDML-fil&quot;">​</a></h4><p>GSDML (Generic Station Description Markup Language) är en XML-fil som beskriver drivet för TIA Portal.</p><p><strong>Ladda ner:</strong></p><ol><li>Gå till <a href="https://support.industry.siemens.com" target="_blank" rel="noreferrer">Siemens Support Portal</a></li><li>Sök efter &quot;G120 GSDML&quot;</li><li>Ladda ner senaste versionen (ex: <code>GSDML-V2.4-Siemens-SINAMICS_G-20231215.xml</code>)</li></ol><p><strong>Installera i TIA Portal:</strong></p><ol><li><strong>Options</strong> → <strong>Install GSD file</strong></li><li>Bläddra till nedladdad XML</li><li>Installera → G120 visas nu i Hardware catalog</li></ol><h4 id="_2-fysisk-anslutning" tabindex="-1">2. Fysisk anslutning <a class="header-anchor" href="#_2-fysisk-anslutning" aria-label="Permalink to &quot;2. Fysisk anslutning&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[PLC Profinet-port] ────(Cat5e/Cat6)──── [G120 CU250S-2 PN port X150]</span></span></code></pre></div><p><strong>Strömanslutning:</strong></p><ul><li>L1, L2, L3 (3-fas 400V)</li><li>Motor U, V, W</li><li>24V DC för styrning (ström från PLC eller extern)</li></ul><h3 id="konfiguration-i-tia-portal" tabindex="-1">Konfiguration i TIA Portal <a class="header-anchor" href="#konfiguration-i-tia-portal" aria-label="Permalink to &quot;Konfiguration i TIA Portal&quot;">​</a></h3><h4 id="steg-1-lagg-till-g120-i-projektet" tabindex="-1">Steg 1: Lägg till G120 i projektet <a class="header-anchor" href="#steg-1-lagg-till-g120-i-projektet" aria-label="Permalink to &quot;Steg 1: Lägg till G120 i projektet&quot;">​</a></h4><ol><li>Öppna <strong>Device view</strong></li><li>Från <strong>Hardware catalog</strong>, sök &quot;G120&quot;</li><li>Välj rätt modell och CU (ex: <strong>G120 CU250S-2 PN</strong>)</li><li>Dra till <strong>Network view</strong></li></ol><h4 id="steg-2-konfigurera-ip-adress" tabindex="-1">Steg 2: Konfigurera IP-adress <a class="header-anchor" href="#steg-2-konfigurera-ip-adress" aria-label="Permalink to &quot;Steg 2: Konfigurera IP-adress&quot;">​</a></h4><ol><li>Markera G120 i Device view</li><li><strong>Properties</strong> → <strong>Profinet interface</strong></li><li><strong>IP address:</strong> 192.168.0.20 (eller enligt din plan)</li><li><strong>Device name:</strong> <code>drive-m01</code></li></ol><h4 id="steg-3-anslut-till-plc" tabindex="-1">Steg 3: Anslut till PLC <a class="header-anchor" href="#steg-3-anslut-till-plc" aria-label="Permalink to &quot;Steg 3: Anslut till PLC&quot;">​</a></h4><ol><li>I <strong>Network view</strong>, dra linje från PLC till G120</li><li>Profinet-anslutning skapas automatiskt</li></ol><h4 id="steg-4-valj-telegram" tabindex="-1">Steg 4: Välj Telegram <a class="header-anchor" href="#steg-4-valj-telegram" aria-label="Permalink to &quot;Steg 4: Välj Telegram&quot;">​</a></h4><p><strong>Telegram</strong> definierar vilka styrord och statusord som utbyts mellan PLC och drive.</p><p><strong>Vanliga telegram:</strong></p><table tabindex="0"><thead><tr><th>Telegram</th><th>Styrord</th><th>Statusord</th><th>Användning</th></tr></thead><tbody><tr><td><strong>1 (Standard)</strong></td><td>2 ord</td><td>2 ord</td><td>Start/stopp, hastighet</td></tr><tr><td><strong>2</strong></td><td>2 ord</td><td>2 ord</td><td>+ ramp-tid</td></tr><tr><td><strong>3</strong></td><td>4 ord</td><td>4 ord</td><td>+ mer status</td></tr><tr><td><strong>20 (SINAMICS)</strong></td><td>6 ord</td><td>6 ord</td><td>Full funktionalitet</td></tr></tbody></table><p><strong>Välj telegram:</strong></p><ol><li>Markera G120 → <strong>Properties</strong></li><li><strong>Configuration</strong> → <strong>Telegram:</strong> Välj <strong>Telegram 1</strong> (standard)</li></ol><div class="tip custom-block"><p class="custom-block-title">Standard: Telegram 1</p><p>För enkel styrning (start/stopp + hastighet), använd <strong>Telegram 1</strong>. Det täcker 90% av användningsfallen.</p></div><h4 id="steg-5-tilldela-i-o-adresser" tabindex="-1">Steg 5: Tilldela I/O-adresser <a class="header-anchor" href="#steg-5-tilldela-i-o-adresser" aria-label="Permalink to &quot;Steg 5: Tilldela I/O-adresser&quot;">​</a></h4><p>När G120 är konfigurerad, skapar TIA Portal automatiskt I/O-adresser.</p><p><strong>Exempel (Telegram 1):</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Styrord (Control Word):     %QW100   (WORD till drive)</span></span>
<span class="line"><span>Hastighetsvärde (Setpoint): %QW102   (INT till drive)</span></span>
<span class="line"><span>Statusord (Status Word):    %IW100   (WORD från drive)</span></span>
<span class="line"><span>Faktisk hastighet:          %IW102   (INT från drive)</span></span></code></pre></div><p>Du kan ändra adresser via: Högerklicka G120 → <strong>Properties</strong> → <strong>I/O addresses</strong></p><h2 id="styra-frekvensomriktare-fran-plc" tabindex="-1">Styra frekvensomriktare från PLC <a class="header-anchor" href="#styra-frekvensomriktare-fran-plc" aria-label="Permalink to &quot;Styra frekvensomriktare från PLC&quot;">​</a></h2><h3 id="styrord-control-word" tabindex="-1">Styrord (Control Word) <a class="header-anchor" href="#styrord-control-word" aria-label="Permalink to &quot;Styrord (Control Word)&quot;">​</a></h3><p>Styrord är ett <strong>WORD (16 bitar)</strong> som skickar kommandon till drivet.</p><p><strong>Viktigaste bitar (Telegram 1):</strong></p><table tabindex="0"><thead><tr><th>Bit</th><th>Namn</th><th>Funktion</th></tr></thead><tbody><tr><td><strong>0</strong></td><td>ON/OFF1</td><td>1 = Tillåt körning, 0 = Stopp</td></tr><tr><td><strong>2</strong></td><td>Quick stop</td><td>1 = Normal, 0 = Snabbstopp</td></tr><tr><td><strong>3</strong></td><td>Enable operation</td><td>1 = Aktivera drift</td></tr><tr><td><strong>6</strong></td><td>Ramp function generator</td><td>1 = Aktivera hastighetsramp</td></tr><tr><td><strong>7</strong></td><td>Fault acknowledge</td><td>1 = Kvittera fel</td></tr><tr><td><strong>10</strong></td><td>Control via PLC</td><td>1 = PLC-styrning, 0 = Lokal styrning</td></tr></tbody></table><p><strong>Standardvärde för körning:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Binärt:  0000 0100 0100 0111 = 16#047E</span></span></code></pre></div><h3 id="hastighetsvarde-speed-setpoint" tabindex="-1">Hastighetsvärde (Speed Setpoint) <a class="header-anchor" href="#hastighetsvarde-speed-setpoint" aria-label="Permalink to &quot;Hastighetsvärde (Speed Setpoint)&quot;">​</a></h3><p>Hastighetsvärdet är ett <strong>INT</strong> som anger önskad hastighet.</p><p><strong>Skalning:</strong></p><ul><li><strong>0</strong> = 0% hastighet</li><li><strong>16384</strong> (16#4000) = 100% hastighet (rated speed)</li><li><strong>32767</strong> = 200% (om överhastigheit tillåten)</li></ul><p><strong>Exempel:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1500 rpm motor, vill köra 50%:</span></span>
<span class="line"><span>Setpoint = 16384 * 0.50 = 8192</span></span></code></pre></div><h3 id="plc-program-grundlaggande-styrning" tabindex="-1">PLC-program: Grundläggande styrning <a class="header-anchor" href="#plc-program-grundlaggande-styrning" aria-label="Permalink to &quot;PLC-program: Grundläggande styrning&quot;">​</a></h3><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Variabler (PLC tags)</span></span>
<span class="line"><span>VAR</span></span>
<span class="line"><span>    Drive_Enable : BOOL;           // Från HMI eller knapp</span></span>
<span class="line"><span>    Drive_SpeedPercent : REAL;     // Hastighet i % (0-100)</span></span>
<span class="line"><span>    Drive_ControlWord : WORD;      // Till %QW100</span></span>
<span class="line"><span>    Drive_SpeedSetpoint : INT;     // Till %QW102</span></span>
<span class="line"><span>    Drive_StatusWord : WORD;       // Från %IW100</span></span>
<span class="line"><span>    Drive_ActualSpeed : INT;       // Från %IW102</span></span>
<span class="line"><span>    Drive_Running : BOOL;          // Status: Motor igång</span></span>
<span class="line"><span>    Drive_Fault : BOOL;            // Status: Fel aktivt</span></span>
<span class="line"><span>END_VAR</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Program (i OB1)</span></span>
<span class="line"><span>// ======================================</span></span>
<span class="line"><span>// Skapa styrord</span></span>
<span class="line"><span>// ======================================</span></span>
<span class="line"><span>IF Drive_Enable THEN</span></span>
<span class="line"><span>    // Starta motor: Sätt ON, Enable, Ramp</span></span>
<span class="line"><span>    Drive_ControlWord := 16#047F;  // 0000 0100 0111 1111</span></span>
<span class="line"><span>ELSE</span></span>
<span class="line"><span>    // Stoppa motor: Nollställ ON-bit</span></span>
<span class="line"><span>    Drive_ControlWord := 16#047E;  // 0000 0100 0111 1110</span></span>
<span class="line"><span>END_IF;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// ======================================</span></span>
<span class="line"><span>// Beräkna hastighetsvärde</span></span>
<span class="line"><span>// ======================================</span></span>
<span class="line"><span>// Skala % till INT (0-100% → 0-16384)</span></span>
<span class="line"><span>Drive_SpeedSetpoint := REAL_TO_INT(Drive_SpeedPercent * 163.84);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// ======================================</span></span>
<span class="line"><span>// Skriv till drive</span></span>
<span class="line"><span>// ======================================</span></span>
<span class="line"><span>%QW100 := Drive_ControlWord;</span></span>
<span class="line"><span>%QW102 := Drive_SpeedSetpoint;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// ======================================</span></span>
<span class="line"><span>// Läs status från drive</span></span>
<span class="line"><span>// ======================================</span></span>
<span class="line"><span>Drive_StatusWord := %IW100;</span></span>
<span class="line"><span>Drive_ActualSpeed := %IW102;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Tolka statusord</span></span>
<span class="line"><span>Drive_Running := (Drive_StatusWord.%X2);      // Bit 2: Drive följer referens</span></span>
<span class="line"><span>Drive_Fault := (Drive_StatusWord.%X3);        // Bit 3: Fel aktivt</span></span></code></pre></div><h3 id="hmi-integration" tabindex="-1">HMI-integration <a class="header-anchor" href="#hmi-integration" aria-label="Permalink to &quot;HMI-integration&quot;">​</a></h3><p><strong>På HMI:</strong></p><ul><li><strong>Button &quot;Start&quot;:</strong> Sätter <code>Drive_Enable := TRUE</code></li><li><strong>Button &quot;Stop&quot;:</strong> Sätter <code>Drive_Enable := FALSE</code></li><li><strong>Slider &quot;Hastighet&quot;:</strong> Skriver till <code>Drive_SpeedPercent</code> (0-100)</li><li><strong>Gauge &quot;Verklig hastighet&quot;:</strong> Visar <code>Drive_ActualSpeed</code> (skalat till rpm)</li></ul><h2 id="statusord-status-word" tabindex="-1">Statusord (Status Word) <a class="header-anchor" href="#statusord-status-word" aria-label="Permalink to &quot;Statusord (Status Word)&quot;">​</a></h2><p>Statusord är ett <strong>WORD</strong> från drivet som anger dess tillstånd.</p><p><strong>Viktigaste bitar:</strong></p><table tabindex="0"><thead><tr><th>Bit</th><th>Namn</th><th>Beskrivning</th></tr></thead><tbody><tr><td><strong>0</strong></td><td>Ready to switch on</td><td>Drive redo att aktiveras</td></tr><tr><td><strong>1</strong></td><td>Ready to operate</td><td>Drive redo att köra</td></tr><tr><td><strong>2</strong></td><td>Operation enabled</td><td>Drive kör</td></tr><tr><td><strong>3</strong></td><td>Fault</td><td>Fel aktivt</td></tr><tr><td><strong>6</strong></td><td>Switch on inhibited</td><td>Körning blockerad</td></tr><tr><td><strong>7</strong></td><td>Warning</td><td>Varning (ej kritiskt)</td></tr><tr><td><strong>13</strong></td><td>Motor rotating</td><td>Motor roterar</td></tr></tbody></table><p><strong>Exempel - tolka statusord:</strong></p><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>IF (Drive_StatusWord AND 16#0004) &lt;&gt; 0 THEN</span></span>
<span class="line"><span>    // Bit 2 är satt → Motor kör</span></span>
<span class="line"><span>    Drive_Running := TRUE;</span></span>
<span class="line"><span>END_IF;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>IF (Drive_StatusWord AND 16#0008) &lt;&gt; 0 THEN</span></span>
<span class="line"><span>    // Bit 3 är satt → Fel aktivt</span></span>
<span class="line"><span>    Drive_Fault := TRUE;</span></span>
<span class="line"><span>    Drive_FaultCode := %IW104;  // Läs felkod (om telegram tillåter)</span></span>
<span class="line"><span>END_IF;</span></span></code></pre></div><h2 id="felhantering" tabindex="-1">Felhantering <a class="header-anchor" href="#felhantering" aria-label="Permalink to &quot;Felhantering&quot;">​</a></h2><h3 id="vanliga-felkoder" tabindex="-1">Vanliga felkoder <a class="header-anchor" href="#vanliga-felkoder" aria-label="Permalink to &quot;Vanliga felkoder&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Felkod</th><th>Beskrivning</th><th>Åtgärd</th></tr></thead><tbody><tr><td><strong>F0001</strong></td><td>Överström</td><td>Kontrollera motor och last</td></tr><tr><td><strong>F0002</strong></td><td>Överspänning</td><td>Kontrollera nätspänning</td></tr><tr><td><strong>F0003</strong></td><td>Övertemperatur</td><td>Kontrollera kylning, minska last</td></tr><tr><td><strong>F0011</strong></td><td>Motor överbelastad</td><td>Minska last eller öka motor</td></tr><tr><td><strong>F7010</strong></td><td>Communication fault</td><td>Kontrollera Profinet-kabel</td></tr><tr><td><strong>F7011</strong></td><td>Telegram error</td><td>Verifiera telegram-typ i TIA Portal</td></tr></tbody></table><h3 id="kvittera-fel-fran-plc" tabindex="-1">Kvittera fel från PLC <a class="header-anchor" href="#kvittera-fel-fran-plc" aria-label="Permalink to &quot;Kvittera fel från PLC&quot;">​</a></h3><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Kvittera fel genom att pulsa bit 7 i Control Word</span></span>
<span class="line"><span>IF Drive_Fault AND #AckButton THEN</span></span>
<span class="line"><span>    Drive_ControlWord.%X7 := TRUE;   // Sätt Fault Ack</span></span>
<span class="line"><span>    #AckTimer(IN := TRUE, PT := T#500ms);</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    IF #AckTimer.Q THEN</span></span>
<span class="line"><span>        Drive_ControlWord.%X7 := FALSE;  // Återställ efter 500ms</span></span>
<span class="line"><span>        #AckTimer(IN := FALSE);</span></span>
<span class="line"><span>    END_IF;</span></span>
<span class="line"><span>END_IF;</span></span></code></pre></div><h2 id="avancerad-styrning" tabindex="-1">Avancerad styrning <a class="header-anchor" href="#avancerad-styrning" aria-label="Permalink to &quot;Avancerad styrning&quot;">​</a></h2><h3 id="pid-reglering-av-hastighet" tabindex="-1">PID-reglering av hastighet <a class="header-anchor" href="#pid-reglering-av-hastighet" aria-label="Permalink to &quot;PID-reglering av hastighet&quot;">​</a></h3><p>För applikationer som kräver exakt hastighetshållning (ex: matning, pump):</p><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// PID-regler för hastighet</span></span>
<span class="line"><span>&quot;PID_Speed&quot;(</span></span>
<span class="line"><span>    Setpoint := #DesiredSpeed,       // Önskad hastighet (rpm)</span></span>
<span class="line"><span>    Input := #Drive_ActualSpeed,     // Verklig hastighet från drive</span></span>
<span class="line"><span>    Output =&gt; #PID_Output            // PID-utgång (0-16384)</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Skicka PID-utgång till drive</span></span>
<span class="line"><span>Drive_SpeedSetpoint := #PID_Output;</span></span></code></pre></div><h3 id="ramptid" tabindex="-1">Ramptid <a class="header-anchor" href="#ramptid" aria-label="Permalink to &quot;Ramptid&quot;">​</a></h3><p>Ramptid kontrollerar hur snabbt motorn accelererar/bromsar.</p><p><strong>Sätt i drive (via HMI eller Startdrive):</strong></p><ul><li>Parameter <strong>p1120</strong> (Ramp-up time): 5.0 s</li><li>Parameter <strong>p1121</strong> (Ramp-down time): 10.0 s</li></ul><p><strong>Eller från PLC via PROFIdrive:</strong></p><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Skriv ramp-tid (kräver Telegram 20+)</span></span>
<span class="line"><span>%QW104 := 5000;</span><span>   // Ramp-up: 5.0 s (millisekunder)</span></span>
<span class="line"><span>%QW106 := 10000;</span><span>  // Ramp-down: 10.0 s</span></span></code></pre></div><h3 id="multi-motor-setup" tabindex="-1">Multi-motor setup <a class="header-anchor" href="#multi-motor-setup" aria-label="Permalink to &quot;Multi-motor setup&quot;">​</a></h3><p>För system med flera motorer:</p><p><strong>Metod 1: Separata drives</strong></p><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Motor 1</span></span>
<span class="line"><span>%QW100 := Drive1_ControlWord;</span></span>
<span class="line"><span>%QW102 := Drive1_SpeedSetpoint;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Motor 2</span></span>
<span class="line"><span>%QW110 := Drive2_ControlWord;</span></span>
<span class="line"><span>%QW112 := Drive2_SpeedSetpoint;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Motor 3</span></span>
<span class="line"><span>%QW120 := Drive3_ControlWord;</span></span>
<span class="line"><span>%QW122 := Drive3_SpeedSetpoint;</span></span></code></pre></div><p><strong>Metod 2: Array-baserad</strong></p><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TYPE &quot;Drive_Type&quot;</span></span>
<span class="line"><span>STRUCT</span></span>
<span class="line"><span>    ControlWord : WORD;</span></span>
<span class="line"><span>    SpeedSetpoint : INT;</span></span>
<span class="line"><span>    StatusWord : WORD;</span></span>
<span class="line"><span>    ActualSpeed : INT;</span></span>
<span class="line"><span>END_STRUCT;</span></span>
<span class="line"><span>END_TYPE</span></span>
<span class="line"><span></span></span>
<span class="line"><span>VAR</span></span>
<span class="line"><span>    Drives : ARRAY[1..3] OF &quot;Drive_Type&quot;;</span></span>
<span class="line"><span>END_VAR</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Loop igenom drives</span></span>
<span class="line"><span>FOR i := 1 TO 3 DO</span></span>
<span class="line"><span>    // Skriv till drive</span></span>
<span class="line"><span>    MOVE_BLK_VARIANT(</span></span>
<span class="line"><span>        SRC := Drives[i].ControlWord,</span></span>
<span class="line"><span>        DEST := %QW(100 + (i-1)*10)</span></span>
<span class="line"><span>    );</span></span>
<span class="line"><span>END_FOR;</span></span></code></pre></div><h2 id="best-practices" tabindex="-1">Best practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best practices&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Rekommendationer</p><ol><li><strong>Använd Telegram 1:</strong> Räcker för de flesta applikationer</li><li><strong>IP-planering:</strong> Dokumentera IP-adresser för alla drives</li><li><strong>Device names:</strong> Ge drives beskrivande namn (<code>drive-m01</code>, <code>drive-pump-01</code>)</li><li><strong>Felhantering:</strong> Implementera automatisk felkvittering med timer</li><li><strong>HMI-indikering:</strong> Visa tydligt motor-status (igång, fel, varning)</li><li><strong>Ramptider:</strong> Sätt lämpliga ramptider för att skydda mekanik</li><li><strong>Överströmsskydd:</strong> Konfigurera korrekt motorström i drive-parametrar</li><li><strong>Test:</strong> Testa alltid manuell körning innan PLC-styrning</li><li><strong>Dokumentation:</strong> Dokumentera telegram-typ och I/O-adresser</li><li><strong>Firmware:</strong> Håll drive-firmware uppdaterad</li></ol></div><h2 id="felsokning" tabindex="-1">Felsökning <a class="header-anchor" href="#felsokning" aria-label="Permalink to &quot;Felsökning&quot;">​</a></h2><h3 id="problem-drive-svarar-inte" tabindex="-1">Problem: Drive svarar inte <a class="header-anchor" href="#problem-drive-svarar-inte" aria-label="Permalink to &quot;Problem: Drive svarar inte&quot;">​</a></h3><p><strong>Checklista:</strong></p><ul><li>✅ Grön LED på X150 (Profinet-port)?</li><li>✅ Rätt IP-adress och device name?</li><li>✅ GSDML-fil installerad i TIA Portal?</li><li>✅ Telegram-typ korrekt konfigurerad?</li><li>✅ 24V DC till drive?</li></ul><h3 id="problem-motor-startar-inte" tabindex="-1">Problem: Motor startar inte <a class="header-anchor" href="#problem-motor-startar-inte" aria-label="Permalink to &quot;Problem: Motor startar inte&quot;">​</a></h3><p><strong>Checklista:</strong></p><ul><li>✅ Control Word bit 0 (ON) satt?</li><li>✅ Control Word bit 3 (Enable operation) satt?</li><li>✅ Status Word visar &quot;Ready to operate&quot;?</li><li>✅ Ingen felindikering (bit 3 i Status Word)?</li><li>✅ Motorparametrar korrekta (p0304, p0305, p0307)?</li></ul><h3 id="problem-felhastighet" tabindex="-1">Problem: Felhastighet <a class="header-anchor" href="#problem-felhastighet" aria-label="Permalink to &quot;Problem: Felhastighet&quot;">​</a></h3><p><strong>Checklista:</strong></p><ul><li>✅ Skalning korrekt (0-16384 = 0-100%)?</li><li>✅ Parameter p2000 (referensfrekvens) satt korrekt?</li><li>✅ Maxhastighet (p1082) korrekt?</li></ul><h2 id="resurser" tabindex="-1">Resurser <a class="header-anchor" href="#resurser" aria-label="Permalink to &quot;Resurser&quot;">​</a></h2><ul><li><a href="https://support.industry.siemens.com/cs/products?search=sinamics%20g120" target="_blank" rel="noreferrer">Siemens: SINAMICS G120 dokumentation (sökresultat)</a></li><li><a href="https://www.youtube.com/watch?v=cN5NvZlGLYc" target="_blank" rel="noreferrer">Video: G120 Profinet Setup</a></li><li><a href="https://www.youtube.com/watch?v=Vt4TFlA3Pv0" target="_blank" rel="noreferrer">Video: PLC to Drive Communication</a></li><li><a href="https://support.industry.siemens.com/cs/products?search=startdrive" target="_blank" rel="noreferrer">Startdrive Configuration Tool</a> (för avancerad drive-konfiguration)</li></ul><hr><p><strong>Relaterat:</strong></p><ul><li><a href="./profinet.html">Profinet-kommunikation</a></li><li><a href="./../03-konfiguration/frekvensomriktare-profinet.html">Konfiguration av Profinet-enheter</a></li></ul>`,98)])])}const u=t(r,[["render",i]]);export{h as __pageData,u as default};
